def load() -> pd.DataFrame:
    import pandas as pd
    path = 'data/biomedical/input/1-s2.0-S0092867420301070-mmc1.xlsx'
    xl = pd.ExcelFile(path)
    sheets = xl.sheet_names
    # sample first 5 rows from each sheet
    out = []
    for sh in sheets:
        df = xl.parse(sh)
        out.append(pd.DataFrame({
            'sheet': [sh],
            'nrows': [df.shape[0]],
            'ncols': [df.shape[1]],
            'columns': [', '.join(map(str, df.columns.tolist()[:50]))]
        }))
    return pd.concat(out, ignore_index=True)

def load() -> pd.DataFrame:
    import pandas as pd
